@MainActor final class MusicModel:ObservableObject {
    @Published var snapshot=Snapshot();@Published var state=LocalState();@Published var status="loading";@Published var query="";let api=MusicAPI();let player=NativePlayer()
    init(){loadLocal();Task{await refresh()};player.onPosition={ [weak self] id,pos in guard let self else{return};self.state.trackId=id;self.state.position=pos;self.saveLocal();let ref=self.session(id);Task{try? await self.api.reportPosition(id:id,session:ref,position:pos,completed:false)}};player.onComplete={ [weak self] id,pos in guard let self else{return};let ref=self.session(id);Task{try? await self.api.reportPosition(id:id,session:ref,position:pos,completed:true)};UserDefaults.standard.removeObject(forKey:"playback-session-\(id)");if let at=self.state.queue.firstIndex(of:id),at+1<self.state.queue.count,let next=self.snapshot.catalog.first(where:{$0.id==self.state.queue[at+1]}){self.state.position=0;self.play(next)}}}
    var filtered:[Track]{query.isEmpty ? snapshot.catalog:snapshot.catalog.filter{($0.title+" "+$0.artistName+" "+($0.album ?? "")).localizedCaseInsensitiveContains(query)}}
    func refresh()async{status="loading";do{snapshot=try await api.snapshot();state.favorites=snapshot.listener.favorites;state.queue=snapshot.listener.queue;state.downloads.merge(snapshot.listener.downloads){local,_ in local};saveLocal();status="ready"}catch{status="offline_mode"}}
    func play(_ track:Track){let offline=offlineURL(track.id),url=FileManager.default.fileExists(atPath:offline.path) ? offline:api.base.appending(path:"api/tracks/\(track.id)/media");player.play(track:track,url:url,position:state.trackId==track.id ? state.position:0)}
    func favorite(_ id:String){state.favorites.contains(id) ? state.favorites.removeAll{$0==id}:state.favorites.append(id);saveLocal();syncLibrary()}
    func enqueue(_ id:String){if !state.queue.contains(id){state.queue.append(id);saveLocal();syncLibrary()}}
    func download(_ id:String){status="downloading";Task{do{_ = try await api.download(id);state.downloads[id]="available";saveLocal();try await api.saveLibrary(favorites:state.favorites,queue:state.queue,downloads:state.downloads);status="download_ready"}catch{status="download_failed"}}}
    func setAI(_ on:Bool){state.aiEnabled=on;saveLocal()}
    func setProfile(explicit:Bool,privateHistory:Bool){snapshot.profile.explicitAllowed=explicit;snapshot.profile.privateHistory=privateHistory;let profile=snapshot.profile;Task{do{try await api.updateProfile(profile);status="ready"}catch{status="retry"}}}
    func clearPrivate(){Keychain.clear();try? FileManager.default.removeItem(at:stateURL);try? FileManager.default.removeItem(at:stateURL.deletingLastPathComponent().appending(path:"Offline"));state=LocalState();snapshot=Snapshot();status="offline_mode"}
    private func offlineURL(_ id:String)->URL{(try? FileManager.default.url(for:.applicationSupportDirectory,in:.userDomainMask,appropriateFor:nil,create:true))!.appending(path:"Offline/\(id).wav")}
    private var stateURL:URL{try! FileManager.default.url(for:.applicationSupportDirectory,in:.userDomainMask,appropriateFor:nil,create:true).appending(path:"music-state.json")}
    private func loadLocal(){if let d=try? Data(contentsOf:stateURL),let s=try? JSONDecoder().decode(LocalState.self,from:d){state=s}}
    private func saveLocal(){if let d=try? JSONEncoder().encode(state){try? d.write(to:stateURL,options:.atomic)}}
    private func syncLibrary(){let favorites=state.favorites,queue=state.queue,downloads=state.downloads;Task{try? await api.saveLibrary(favorites:favorites,queue:queue,downloads:downloads)}}
    private func session(_ id:String)->String{let key="playback-session-\(id)";if let value=UserDefaults.standard.string(forKey:key){return value};let value=UUID().uuidString;UserDefaults.standard.set(value,forKey:key);return value}
}

@MainActor final class NativePlayer {
    private var player:AVPlayer?
    private var observer:Any?
    private var completion:Any?
    var onPosition:((String,Double)->Void)?
    var onComplete:((String,Double)->Void)?
    private var id=""

    init(){try? AVAudioSession.sharedInstance().setCategory(.playback,mode:.default,options:[]);try? AVAudioSession.sharedInstance().setActive(true);MPRemoteCommandCenter.shared().playCommand.addTarget{[weak self]_ in self?.player?.play();return .success};MPRemoteCommandCenter.shared().pauseCommand.addTarget{[weak self]_ in self?.player?.pause();return .success}}

    func play(track:Track,url:URL,position:Double){
        id=track.id
        if let observer,let player{player.removeTimeObserver(observer)}
        if let completion{NotificationCenter.default.removeObserver(completion)}
        let asset=AVURLAsset(url:url)
        let item=AVPlayerItem(asset:asset)
        player=AVPlayer(playerItem:item)
        if position>0{player?.seek(to:CMTime(seconds:position,preferredTimescale:1000))}
        player?.play()
        MPNowPlayingInfoCenter.default().nowPlayingInfo=[MPMediaItemPropertyTitle:track.title,MPMediaItemPropertyArtist:track.artistName,MPMediaItemPropertyPlaybackDuration:Double(track.durationMillis)/1000]
        observer=player?.addPeriodicTimeObserver(forInterval:CMTime(seconds:5,preferredTimescale:1),queue:.main){[weak self] time in
            let seconds=time.seconds
            Task{@MainActor [weak self] in guard let self else{return};self.onPosition?(self.id,seconds)}
        }
        let duration=Double(track.durationMillis)/1000
        completion=NotificationCenter.default.addObserver(forName:.AVPlayerItemDidPlayToEndTime,object:item,queue:.main){[weak self]_ in
            Task{@MainActor [weak self] in guard let self else{return};self.onComplete?(self.id,duration)}
        }
    }
}

struct TrackDetail:View{@EnvironmentObject var m:MusicModel;@EnvironmentObject var l:I18n;let t:Track;@State var reason="";@State var evidence="";var body:some View{Form{Section(t.title){Text(t.artistName);if let album=t.album,!album.isEmpty{Text(album)};Text("\(l.t("rights")): \(t.rights.basis) · \(t.rights.evidenceRef)");Text("\(l.t("provenance")): \(t.provenance["audio"] ?? "")")};Section(l.t("rights")){TextField(l.t("rights_declaration"),text:$reason);TextField(l.t("rights_evidence"),text:$evidence);ForEach(["report","dispute","appeal"],id:\.self){kind in Button(kind.capitalized){Task{try? await m.api.openCase(kind:kind,track:t.id,reason:reason,evidence:evidence);await m.refresh()}}.disabled(reason.count<5||evidence.isEmpty)}}}.navigationTitle(t.title)}}
struct TrackRow:View { @EnvironmentObject var m:MusicModel;let t:Track;@EnvironmentObject var l:I18n;var body:some View{VStack(alignment:.leading,spacing:8){NavigationLink{TrackDetail(t:t)}label:{VStack(alignment:.leading){Text(t.title).font(.headline);Text(t.artistName+(t.album.map{" · "+$0} ?? "")).font(.subheadline)}};Text("\(l.t("rights")): \(t.rights.basis) · \(l.t("provenance")): \(t.provenance["audio"] ?? "")").font(.caption).foregroundStyle(.secondary);HStack{Button(l.t("play")){m.play(t)};Button(l.t("favorite")){m.favorite(t.id)};Button(l.t("add_queue")){m.enqueue(t.id)};Button(l.t("download")){m.download(t.id)}}}.accessibilityElement(children:.contain).padding(.vertical,6)}}
struct HomeView:View{@EnvironmentObject var m:MusicModel;@EnvironmentObject var l:I18n;@Environment(\.openURL)var openURL;var body:some View{NavigationStack{List{if m.filtered.isEmpty{ContentUnavailableView(l.t("empty_catalog"),systemImage:"music.note",description:Text(l.t("retry")))}else{ForEach(m.filtered){TrackRow(t:$0)}}}.searchable(text:$m.query,prompt:l.t("search_hint")).navigationTitle(l.t("app_name")).toolbar{Button(l.t("sign_in_wallet")){if let u=try? WalletLink.make(){openURL(u)}}}.refreshable{await m.refresh()}}}}
struct LibraryView:View{@EnvironmentObject var m:MusicModel;@EnvironmentObject var l:I18n;@State var playlistName="";var body:some View{NavigationStack{List{Section(l.t("favorites")){ForEach(m.state.favorites,id:\.self){Text($0)}};Section(l.t("queue")){ForEach(m.state.queue,id:\.self){Text($0)}};Section(l.t("download_ready")){ForEach(m.state.downloads.keys.sorted(),id:\.self){Text($0)}};Section(l.t("private_history")){ForEach(m.snapshot.listener.history){Text("\($0.trackId) · \($0.positionMillis) ms")}};Section(l.t("library")){TextField(l.t("library"),text:$playlistName);Button(l.t("upload")){Task{try? await m.api.createPlaylist(name:playlistName,ids:m.state.favorites)}}.disabled(playlistName.isEmpty||m.state.favorites.isEmpty)}}.navigationTitle(l.t("library"))}}}
struct CreatorView:View{@EnvironmentObject var m:MusicModel;@EnvironmentObject var l:I18n;@Environment(\.openURL)var openURL;@State var importing=false;@State var title="";@State var artist="";@State var evidence="";@State var provenance="";@State var proposal:AIProposal?;@State var aiStatus="";var body:some View{NavigationStack{Form{Text(l.t("creator_truth"));TextField(l.t("track_title"),text:$title);TextField(l.t("artist_name"),text:$artist);TextField(l.t("rights_evidence"),text:$evidence);TextField(l.t("provenance"),text:$provenance);Button(l.t("upload_owned_audio")){importing=true}.fileImporter(isPresented:$importing,allowedContentTypes:[.wav]){result in if case .success(let url)=result{Task{let access=url.startAccessingSecurityScopedResource();defer{if access{url.stopAccessingSecurityScopedResource()}};do{try await m.api.uploadOwnedWAV(url,title:title,artist:artist,evidence:evidence,provenance:provenance);await m.refresh()}catch{m.status="upload_failed"}}}};Section(l.t("creator")){ForEach(m.snapshot.creatorTracks){track in HStack{Text(track.title+" · "+track.rights.basis);Spacer();if !m.snapshot.catalog.contains(where:{$0.id==track.id}){Button(l.t("upload")){Task{try? await m.api.release(track.id);await m.refresh()}}}}}};Section(l.t("usage_records")){Text(l.number(m.snapshot.usage.count));Text("YNX Pay: \(l.number(m.snapshot.settlements.count)) · YNX Trust: \(l.number(m.snapshot.cases.count))")};Text(l.t("revenue_truth")).font(.footnote);ForEach(m.snapshot.allocations){allocation in Button("YNX Pay · \(allocation.amountMicros) µYNXT"){Task{if let settlement=try? await m.api.settlement(allocation.id,payTo:m.snapshot.profile.account),let url=URL(string:settlement.reviewUri){openURL(url)};await m.refresh()}}};Button(l.t("ai_enabled")){guard m.state.aiEnabled else{return};Task{do{proposal=try await m.api.createAI(ids:m.state.favorites,language:l.aiLanguage);aiStatus="YNX AI · \(proposal?.status ?? "") · \(proposal?.estimatedUnits ?? 0) units"}catch{aiStatus=l.t("retry")}}}.disabled(!m.state.aiEnabled||m.state.favorites.isEmpty);if let proposal{HStack{Button(l.t("upload")){Task{try? await m.api.reviewAI(id:proposal.id,action:"apply");self.proposal=nil;await m.refresh()}};Button(l.t("cancel"),role:.destructive){Task{try? await m.api.reviewAI(id:proposal.id,action:"reject");self.proposal=nil;await m.refresh()}}}};Text(aiStatus.isEmpty ? l.t("ai_explanation"):aiStatus).font(.footnote)}.navigationTitle(l.t("creator"))}}}
struct SettingsView:View{@EnvironmentObject var m:MusicModel;@EnvironmentObject var l:I18n;var body:some View{NavigationStack{Form{Section{NavigationLink(destination:CreatorView()){Label(l.t("creator"),systemImage:"waveform")};Text(l.t("creator_truth")).font(.footnote).foregroundStyle(.secondary)};Picker(l.t("language"),selection:Binding(get:{l.tag},set:l.set)){Text("System").tag("system");ForEach(["en","zh-Hans","zh-Hant","ja","ko","es","fr","de","pt","ru","ar","id"],id:\.self){Text($0).tag($0)}};Section(l.t("profile")){Toggle(l.t("explicit_content"),isOn:Binding(get:{m.snapshot.profile.explicitAllowed},set:{m.setProfile(explicit:$0,privateHistory:m.snapshot.profile.privateHistory)}));Toggle(l.t("private_history"),isOn:Binding(get:{m.snapshot.profile.privateHistory},set:{m.setProfile(explicit:m.snapshot.profile.explicitAllowed,privateHistory:$0)}))};Toggle(l.t("ai_enabled"),isOn:Binding(get:{m.state.aiEnabled},set:m.setAI));Picker(l.t("ai_output_language"),selection:Binding(get:{l.aiLanguage},set:l.setAI)){Text("System").tag("system");ForEach(["en","zh-Hans","zh-Hant","ja","ko","es","fr","de","pt","ru","ar","id"],id:\.self){Text($0).tag($0)}};Text(l.t("ai_explanation"));Button(l.t("clear_private_data"),role:.destructive){m.clearPrivate()}}.navigationTitle(l.t("settings"))}}}

@main struct YNXMusicApp:App{@StateObject var model=MusicModel();@StateObject var l=I18n.shared;var body:some Scene{WindowGroup{TabView{HomeView().tabItem{Label(l.t("home"),systemImage:"music.note.house")};LibraryView().tabItem{Label(l.t("library"),systemImage:"books.vertical")};SettingsView().tabItem{Label(l.t("settings"),systemImage:"gear")}}.environmentObject(model).environmentObject(l).environment(\.locale,Locale(identifier:l.resolved)).environment(\.layoutDirection,l.rtl ? .rightToLeft:.leftToRight).tint(Color(red:0,green:47/255,blue:167/255)).onOpenURL{url in let items=URLComponents(url:url,resolvingAgainstBaseURL:false)?.queryItems ?? [];guard url.scheme=="ynxmusic",items.count==1,items.first?.name=="response",Date().timeIntervalSince1970<UserDefaults.standard.double(forKey:"walletExpires"),let response=items.first?.value,let raw=UserDefaults.standard.string(forKey:"walletRequest"),let data=raw.data(using:.utf8),let request=try? JSONSerialization.jsonObject(with:data) as? [String:Any] else{return};UserDefaults.standard.removeObject(forKey:"walletRequest");UserDefaults.standard.removeObject(forKey:"walletExpires");Task{do{try await model.api.walletSession(response:response,request:request);await model.refresh()}catch{model.status="auth_rejected"}}}}}}
